var handgoldenRootRE = regexp.MustCompile(`/tmp/handgold-[^/]+`)

var handGolden map[string]any

func loadHandGolden(t *testing.T) map[string]any {
	t.Helper()
	if handGolden != nil {
		return handGolden
	}
	data, err := os.ReadFile("testdata/handdelivery.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	handGolden = g
	return g
}

func handSection(t *testing.T, name string) map[string]any {
	t.Helper()
	v, ok := loadHandGolden(t)[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

// handFold folds BOTH sides' tempdir roots (the generator's
// /tmp/handgold-XXXX and the Go test's t.TempDir()) to "<TMP>".
func handFold(s, root string) string {
	out := handgoldenRootRE.ReplaceAllString(s, "<TMP>")
	if root != "" {
		out = strings.ReplaceAll(out, root, "<TMP>")
	}
	return out
}

// cmpHand byte-compares through the canonical Python dumps.
func cmpHand(t *testing.T, what string, got, want any, root string) {
	t.Helper()
	g := storage.PyDumps(normHand(got, root))
	w := storage.PyDumps(normHand(want, ""))
	if g != w {
		t.Fatalf("%s diverges from the reference golden:\n--- go ---\n%s"+
			"\n--- reference ---\n%s", what, g, w)
	}
}

func normHand(v any, root string) any {
	switch t := v.(type) {
	case string:
		return handFold(t, root)
	case []string:
		out := make([]any, len(t))
		for i, s := range t {
			out[i] = handFold(s, root)
		}
		return out
	case map[string]string:
		out := map[string]any{}
		for k, s := range t {
			out[k] = handFold(s, root)
		}
		return out
	case int:
		return float64(t)
	case int64:
		return float64(t)
	case bool:
		return t
	case float64:
		return t
	case json.Number:
		f, _ := t.Float64()
		return f
	case nil:
		return nil
	case map[string]any:
		out := map[string]any{}
		for k, val := range t {
			out[k] = normHand(val, root)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normHand(val, root)
		}
		return out
	default:
		return t
	}
}

// freezeHandClock freezes the package clock for one test (the
// generator stubs hd.time to 2026-10-17 12:00 — the same seam).
func freezeHandClock(t *testing.T) {
	t.Helper()
	orig := Clock
	Clock = func() time.Time {
		return time.Date(2026, 10, 17, 12, 0, 0, 0, time.Local)
	}
	t.Cleanup(func() { Clock = orig })
}

// fakeRowsState replays the reference DB's rows through the
// RetryRowsState seam (the generator's input list).
type fakeRowsState struct{ rows []RetrySourceRow }

func (f fakeRowsState) AllRetryRows() ([]RetrySourceRow, error) { return f.rows, nil }

func TestGoldenWalledRetryRows(t *testing.T) {
	g := handSection(t, "walled_retry_rows")
	dryrun.Disable()
	dryrun.Clear()
	t.Cleanup(func() { dryrun.Disable() })

	// the input — exactly the rows the reference's real state DB held
	input, ok := g["input"].([]any)
	if !ok {
		t.Fatalf("golden walled_retry_rows.input missing")
	}
	rows := make([]RetrySourceRow, 0, len(input))
	for _, it := range input {
		m, ok := it.(map[string]any)
		if !ok {
			t.Fatalf("input row not an object: %v", it)
		}
		var lastError string
		if s, ok := m["last_error"].(string); ok {
			lastError = s
		}
		rows = append(rows, RetrySourceRow{
			URL:       m["url"].(string),
			LastError: lastError,
			Attempts:  int(m["attempts"].(float64)),
		})
	}

	got := WalledRetryRows(fakeRowsState{rows: rows})
	rich := make([]any, 0, len(got))
	for _, r := range got {
		rich = append(rich, map[string]any{
			"url": r.URL, "wall": r.Wall, "attempts": float64(r.Attempts),
		})
	}
	cmpHand(t, "walled_retry_rows.output", rich, g["output"], "")
}

// buildConsumeVault replays the generator's consume scenario: five
// enqueued links (A,B,C,E then D,F with door=auto), C pre-consumed,
// three delivered pages + an orphan. Returns the vault path.
func buildConsumeVault(t *testing.T, tmp string) string {
	t.Helper()
	vault := filepath.Join(tmp, "vault", "websites")
	A := "https://alpha.example/walled"
	B := "https://beta.example/empty"
	C := "https://gamma.example/consumed"
	D := "https://delta.example/auto"
	E := "https://epsilon.example/waiting"
	F := "https://zeta.example/waiting-too"
	walls := map[string]string{
		A: "HTTP 403 — bot defense (server: cloudflare)",
		B: "HTTP 403 — refused", C: "ssl handshake failed",
		E: "HTTP 429 — rate limited",
	}
	EnqueueHandDelivery(vault, []string{A, B, C, E}, walls, nil, false, "")
	EnqueueHandDelivery(vault, []string{D, F},
		map[string]string{D: "fingerprint mismatch", F: "HTTP 405"},
		nil, false, "auto")
	// a pre-consumed row (an earlier batch took it)
	q := ReadQueue(vault)
	if m := q.Meta(C); m != nil {
		m.Set("consumed", "2026-10-01 10:00")
	}
	if err := q.WriteAtomic(vault); err != nil {
		t.Fatal(err)
	}
	hd := HandDeliveryDir(vault)
	os.MkdirAll(hd, 0o755)
	deliverPage(t, vault, A, []byte("<html><head><title>The Walled Page</title></head><body>the content the browser sees</body></html>"))
	deliverPage(t, vault, B, []byte("   "))
	deliverPage(t, vault, D, []byte("<html><head><title>Auto Real</title></head><body>real live DOM content long enough to be a real page for the fifth door's own verdict</body></html>"))
	if err := os.WriteFile(filepath.Join(hd, "random-orphan.html"), []byte("<html></html>"), 0o644); err != nil {
		t.Fatal(err)
	}
	return vault
}

func deliverPage(t *testing.T, vault, u string, body []byte) {
	t.Helper()
	path := filepath.Join(HandDeliveryDir(vault), SuggestedFilename(u))
	if err := os.WriteFile(path, body, 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestGoldenConsumeDelivered(t *testing.T) {
	g := handSection(t, "consume_delivered")
	dryrun.Disable()
	dryrun.Clear()
	t.Cleanup(func() { dryrun.Disable() })
	freezeHandClock(t)

	tmp := t.TempDir()
	vault := buildConsumeVault(t, tmp)

	var logs []string
	log := func(msg, level string) { logs = append(logs, "["+level+"] "+msg) }
	taken := ConsumeDelivered(vault, log)

	gotTaken := make([]any, 0, len(taken))
	for _, it := range taken {
		gotTaken = append(gotTaken, map[string]any{
			"url":  it.URL,
			"wall": it.Wall,
			"file": it.File,
			"body": string(it.Body),
		})
	}
	cmpHand(t, "consume_delivered.taken", gotTaken, g["taken"], tmp)

	qraw, err := os.ReadFile(QueuePath(vault))
	if err != nil {
		t.Fatal(err)
	}
	if got := handFold(string(qraw), tmp); got != g["queue_after"].(string) {
		t.Errorf("queue.json after the consume diverges:\n--- go ---\n%s\n--- reference ---\n%s",
			got, g["queue_after"].(string))
	}
	cmpHand(t, "consume_delivered.logs", logs, g["logs"], tmp)

	// pending_hand_links rides the same vault (the fifth door's to-do
	// list after the consume) — a golden LIST section
	pendingWant, ok := loadHandGolden(t)["pending_hand_links"].([]any)
	if !ok {
		t.Fatalf("golden section \"pending_hand_links\" missing or not a list")
	}
	pending := PendingHandLinks(vault)
	rich := make([]any, 0, len(pending))
	for _, p := range pending {
		rich = append(rich, map[string]any{"url": p.URL, "wall": p.Wall})
	}
	cmpHand(t, "pending_hand_links", rich, pendingWant, tmp)
}

func TestGoldenStampHandRows(t *testing.T) {
	g := handSection(t, "stamp_hand_rows")
	dryrun.Disable()
	dryrun.Clear()
	t.Cleanup(func() { dryrun.Disable() })
	freezeHandClock(t)

	tmp := t.TempDir()
	tv := filepath.Join(tmp, "stamptable")
	os.MkdirAll(filepath.Join(tv, decomtable.ReviewFolder), 0o755)
	table := filepath.Join(tv, decomtable.ReviewFolder, decomtable.DecommissionTable)
	lines := []string{
		"# Review Master Table — decommission or approve",
		"",
		"> Last updated: 2001-01-01 00:00",
		"",
		"| # | Date | URL | Domain | Source | Status | Notes |",
		"|---|------|-----|--------|--------|--------|-------|",
		"| - | 2026-10-01 | https://hand1.example/a | hand1.example | retry backlog | unreviewed | first |",
		"| 🖐 | 2026-10-01 | https://hand2.example/b | hand2.example | owner | hand | second |",
		"| - | 2026-10-01 | https://other.example/c | other.example | retry backlog | unreviewed | third |",
	}
	if err := os.WriteFile(table, []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	stamped := StampHandRows(tv, []string{"https://hand1.example/a", "https://hand2.example/b"}, nil)
	if float64(stamped) != g["stamped"] {
		t.Errorf("stamp_hand_rows: stamped %d want %v", stamped, g["stamped"])
	}
	gotTable, err := os.ReadFile(table)
	if err != nil {
		t.Fatal(err)
	}
	if got := handFold(string(gotTable), tmp); got != g["table"].(string) {
		t.Errorf("stamped table diverges:\n--- go ---\n%s\n--- reference ---\n%s",
			got, g["table"].(string))
	}
}

func TestGoldenHandFetchResult(t *testing.T) {
	g := handSection(t, "hand_fetch_result")
	dryrun.Disable()
	dryrun.Clear()
	t.Cleanup(func() { dryrun.Disable() })

	body := []byte("<html><head><title>Story</title></head><body>x</body></html>")
	r4 := HandFetchResult("https://alpha.example/walled", body, "HTTP 403 — bot defense", "")
	r5 := HandFetchResult("https://delta.example/auto", body, "fingerprint mismatch", "auto")

	fres := func(r *webfetch.FetchResult) map[string]any {
		var hs any
		if r.HTTPStatus != nil {
			hs = float64(*r.HTTPStatus)
		}
		return map[string]any{
			"url": r.URL, "final_url": r.FinalURL, "status": r.Status,
			"http_status": hs, "content_type": r.ContentType,
			"charset": r.Charset, "reason": r.Reason, "ok": r.OK(),
			"text": r.Text,
		}
	}
	cmpHand(t, "hand_fetch_result.fourth_door", fres(r4), g["fourth_door"], "")
	cmpHand(t, "hand_fetch_result.fifth_door_auto", fres(r5), g["fifth_door_auto"], "")
}
